const fs = require('fs');
const path = require('path');
const dir = path.join(__dirname, 'src', 'assets', 'i18n');

const map = {
  de: { STAR_SELECT: 'Stern wählen', STAR_SELECT_PLACEHOLDER: '— Auswählen —' },
  es: { STAR_SELECT: 'Elegir una estrella', STAR_SELECT_PLACEHOLDER: '— Seleccionar —' },
  it: { STAR_SELECT: 'Scegli una stella', STAR_SELECT_PLACEHOLDER: '— Seleziona —' },
  ru: { STAR_SELECT: 'Выбрать звезду', STAR_SELECT_PLACEHOLDER: '— Выбрать —' },
  cn: { STAR_SELECT: '选择恒星', STAR_SELECT_PLACEHOLDER: '— 请选择 —' },
  jp: { STAR_SELECT: '星を選択', STAR_SELECT_PLACEHOLDER: '— 選択 —' },
  ar: { STAR_SELECT: 'اختر نجماً', STAR_SELECT_PLACEHOLDER: '— اختر —' },
  he: { STAR_SELECT: 'בחירת כוכב', STAR_SELECT_PLACEHOLDER: '— בחירה —' },
  el: { STAR_SELECT: 'Επιλογή αστέρα', STAR_SELECT_PLACEHOLDER: '— Επιλογή —' },
  in: { STAR_SELECT: 'Pilih bintang', STAR_SELECT_PLACEHOLDER: '— Pilih —' }
};

for (const [lang, keys] of Object.entries(map)) {
  const file = path.join(dir, `${lang}.json`);
  const data = JSON.parse(fs.readFileSync(file, 'utf8'));
  Object.assign(data.ASTRO_COMPASS, keys);
  fs.writeFileSync(file, JSON.stringify(data, null, 2) + '\n', 'utf8');
  console.log(lang, 'ok');
}
